# -*- coding: utf-8 -*-
"""Pend part C: costs, balancing, distribution and mental weighing."""
from author_batch200_vid_74a import E,S,K,O
X=[['拉丁 pendere“称量、支付” → ex- + pendere → expendere','称出、付出'],['晚期拉丁 expensa → 古法语 espense／盎格鲁法语 expense','支出、付出的费用'],['中古英语 expense','费用、开支；后来也作报销、记入费用的动词']]
CO=[['拉丁 pendere → pensare','称量 → 反复称量、权衡'],['拉丁 com- + pensare → compensare；分词 compensatus','放在一起称 → 抵平、补足']]
DI=[['拉丁 dis- + pendere → dispendere','分别称出、支付'],['拉丁反复式 dispensare','按份分配、管理；后来也有准予豁免的用法']]
PE=[['拉丁 pendere → pensare','称量 → 权衡、考虑'],['古法语 penser → pensif','思考 → 深思的、忧思的'],['中古英语 pensif／pensyfe → pensive','沉思的，常带忧郁或心事']]
W=[
E('expense','英、美 /ɪkˈspens/','费用；开支；代价；〔工作语境〕把支出报销或列作费用','为了办一件事，你得付出多少钱；也可以把非金钱的损失看成代价。','经古法语 espense、盎格鲁法语 expense，接晚期拉丁名词 expensa，来自 expendere“称出、支付”。它有自己的名词借入路线，不是现代英语 expend 改几个字母才造出来的。',X,'the expense of repairs 是修理费用；at the expense of quality 是以牺牲质量为代价。工作里 expense a meal 可以指按规定把一顿饭的费用报销或记入业务费用，是否允许由具体政策决定。','at great expense；cover the expense；at the expense of；expense a business meal。','expense 强调付出的费用或代价；expensive 是价格高的形容词。at someone’s expense 也可能指拿某人开玩笑，让他成为笑柄。',('We had not expected the expense of replacing the windows.','我们原先没有预料到更换窗户的这笔费用。'),('The shortcut saved time at the expense of accuracy.','这个捷径节省了时间，却牺牲了准确性。'),('The policy explains which travel costs employees may expense.','这项政策解释了员工可以报销哪些差旅费用。'),sources=[S('expense'),K('expense'),O('expense_1'),O('expense_2')]),
E('expenses','英、美 /ɪkˈspensɪz/','各项开支；差旅等报销费用','把支出一笔笔列出来：车票、住宿、材料费，都可能放进 expenses 这一栏。','expense 的复数，-s 在 /s/ 后读 /ɪz/。在工作中常固定用复数表示需要支付或报销的各项费用。',X+[['英语 expense → expenses','多项费用；常用于生活开支与业务报销']],'living expenses 是生活开销；travel expenses 是差旅费；claim expenses 是申请报销。工资通常另算，a job with salary plus expenses 表示薪水之外还支付相关工作费用。','living expenses；travel expenses；claim expenses；keep expenses down。','spending 常看支出总量或行为；expenses 常看一项项费用。expense 单数可以指一项花费，复数 expenses 很适合费用清单。',('Please keep the receipts for your travel expenses.','请保留差旅费用的收据。'),('Rent accounts for a large share of their monthly expenses.','房租占了他们每月开支的很大一部分。'),sources=[K('expenses'),O('expenses'),S('expense')]),
E('expensive','英、美 /ɪkˈspensɪv/','昂贵的；花费很大的','得到它需要付出比较多的钱，或做这件事会花很多钱。高不高，总要放在某个预算和比较对象里看。','英语 expense + -ive；早期也说花钱多、挥霍，后来“成本高、价格高”成为常见意思。-ive 把费用概念转为形容词，不是“正在花钱”的进行时。',X+[['英语 expense + -ive → expensive','花费多的 → 价格或成本高的']],'an expensive coat 是价格高的外套；an expensive mistake 是代价很大的错误，不一定真有一个商品标价。expensive to run 表示使用、运营起来很费钱。','an expensive mistake；expensive to maintain；too expensive for；an expensive habit。','valuable 是价值大，expensive 是价格或成本高；东西贵，不保证对你有价值。expendable 则是可消耗、可替换的，意思完全不同。',('The printer is cheap, but the ink is expensive.','打印机便宜，墨水却很贵。'),('Ignoring the small leak turned out to be an expensive mistake.','没理会那处小漏水，结果成了一个代价很大的错误。'),sources=[S('expensive'),K('expensive'),O('expensive')]),
E('inexpensive','英、美 /ˌɪnɪkˈspensɪv/','不贵的；价格不高的','需要花的钱不多，往往是比较中性、温和地说“便宜”。','英语 in-“不”+ expensive；这里 in- 是否定，不是“在里面”。和 costly 的否定一样，评价的是价格或费用。',X+[['英语 expensive → in- + expensive → inexpensive','昂贵的 → 不昂贵的']],'an inexpensive café 不一定装修简陋；an inexpensive solution 可能既好用又省钱。这个词通常避免 cheap 有时带出的“质量差、显廉价”的感觉。','an inexpensive option；relatively inexpensive；inexpensive to make。','cheap 也可以中性表示便宜，但有时带质量差的暗示；inexpensive 通常只强调价格不高。',('We found an inexpensive hotel near the station.','我们在车站附近找到一家价格不高的旅馆。'),('A simple label is an inexpensive way to prevent confusion.','贴一张简单的标签，就能低成本地避免混淆。'),sources=[S('inexpensive'),K('inexpensive'),O('inexpensive')]),
E('expensively','英、美 /ɪkˈspensɪvli/','花费高地；以昂贵方式；显得穿戴昂贵地','描述事情怎样完成：装修花了大价钱，衣服看起来价格不低，设备修起来很费钱。','英语 expensive + -ly。副词可以描写动作的高花费，也可以修饰 dressed、furnished 等分词。',X+[['英语 expensive + -ly → expensively','以高成本或使用昂贵物品的方式']],'expensively dressed 是穿戴看起来昂贵；expensively furnished 是用贵重家具布置。它描述花费或外观，不等于判断设计一定好看。','expensively dressed；expensively furnished；expensively produced。','elegantly 说优雅，expensively 说花费高；精心搭配的旧衣服也可能 elegant，而不 expensive。',('The room was expensively furnished but felt unwelcoming.','房间布置得很昂贵，却让人觉得不亲切。'),('An expensively dressed man waited by the entrance.','一个穿戴昂贵的男人在入口旁等着。'),sources=[K('expensively'),O('expensively'),S('expensive')]),
E('inexpensively','英、美 /ˌɪnɪkˈspensɪvli/','低成本地；不花很多钱地','同样办成一件事，用的钱比较少：吃饭、装饰、修补，都可以低成本完成。','英语 inexpensive + -ly；in- 否定昂贵，-ly 描写完成动作的方式。',X+[['英语 expensive → inexpensive → inexpensively','费用高 → 不贵 → 低成本地']],'eat inexpensively 是吃饭不花很多钱；decorate inexpensively 是用较少的钱布置。它没有自动保证质量好，但也不暗示粗制滥造。','live inexpensively；eat inexpensively；produce inexpensively；repair inexpensively。','inexpensively 说花费，simply 说方式简单。简单的方法可能贵，便宜的方法也可能需要复杂准备。',('You can eat inexpensively at the market stalls.','在市场摊位上吃饭花费不高。'),('The display was made inexpensively from reused cardboard.','这个展示装置用回收纸板低成本制作而成。'),sources=[K('inexpensively'),O('inexpensively'),S('inexpensive')]),
E('compensate','英 /ˈkɒmpenseɪt/；美 /ˈkɑːmpenseɪt/','补偿；弥补；抵消不足','天平一边少了，就在另一边补一些东西，让损失、缺点或付出得到一定平衡。','借拉丁 compensare 的分词词干 compensat-；com-“一起”+ pensare“称量、权衡”。现代可见 -ate 动词形式，实际来源是已有拉丁动词，不是英语先有 compensation 再随意拆出。',CO+[['拉丁 compensatus／compensat- → 英语 compensate','抵平、弥补；后来也常说向人支付补偿']],'compensate for a weakness 是弥补弱点；compensate someone for a loss 是补偿某人的损失。补偿不保证让损失完全消失，也不一定只能用钱。','compensate for；compensate someone for；fully compensate；compensate with。','refund 是退还已付款项，compensate 更宽，可以为损失、额外付出或不便作补偿。make up for 是较日常的相近表达。',('The large windows compensate for the room’s small size.','大窗户弥补了房间面积小的不足。'),('The company offered to compensate customers for the delay.','公司提出对顾客因延误受到的影响给予补偿。'),sources=[S('compensate'),K('compensate'),O('compensate')]),
E('compensation','英 /ˌkɒmpenˈseɪʃən/；美 /ˌkɑːmpenˈseɪʃən/','补偿；赔偿；报酬、薪酬','把“补回来”的结果当成一项给付或安排：可以是弥补损失的钱，也可以是工作换来的薪酬。','接拉丁 compensatio／compensationem，来自 compensare 的词族。英语名词记录早于常用动词 compensate，不能在历史里只画成英语动词加 -ion。',CO+[['拉丁 compensatio／compensationem → 中古英语 compensation','抵平、弥补的动作或结果名词'],['现代 employment 等用法','损失补偿；工作报酬或薪酬安排']],'compensation for damage 是损失补偿；a compensation package 在招聘中通常说薪酬及相关待遇。具体包含哪些项目要看上下文，不能每次都翻成赔偿金。','receive compensation；compensation for；a compensation package；adequate compensation。','compensation 可以指报酬或补偿；complaint 是投诉，读音和拼写有一点像，但与这条称量词根无关。',('They received compensation for the damaged equipment.','他们为受损设备获得了补偿。'),('The job advertisement describes the compensation package.','招聘广告介绍了这份工作的薪酬待遇。'),sources=[S('compensation'),K('compensation'),O('compensation')]),
E('compensatory','英 /ˌkɒmpenˈseɪtəri/；美 /kəmˈpensətɔːri/','补偿性的；用于弥补或抵消的','不是只说“给了某样东西”，而是说给它的目的在于弥补另一处损失或不足。','经法语 compensatoire 或依其形成，远接拉丁 compensare、compensatus。英语形容词的记录早于 compensate 的常见记录；现代虽能和 compensate、-ory 对看，不应因此把它画成后来的英语动词直接派生。',CO+[['法语 compensatoire → 英语 compensatory','用于抵平、补偿的'],['现代形容词用法','说明给付、变化或机制起弥补作用']],'a compensatory payment 是补偿性给付；a compensatory adjustment 是为了抵消另一变化而作的调整。英式常把重音放在 /ˈseɪ/，美式常用 /ˈpen/。','a compensatory payment；a compensatory mechanism；a compensatory adjustment。','compensatory 强调补偿的作用，complementary 强调补充配合，不一定存在损失要补。',('The agreement includes a compensatory payment for the cancelled event.','协议包含因活动取消而支付的补偿款。'),('The model includes a compensatory adjustment when one input falls.','模型在一个输入量下降时包含一项补偿性调整。'),sources=[S('compensatory'),K('compensatory'),O('compensatory')]),
E('uncompensated','英 /ˌʌnˈkɒmpənseɪtɪd/；美 /ˌʌnˈkɑːmpənseɪtɪd/','未获补偿的；未付报酬的','已经付出时间、劳动或承担损失，却没有获得相应报酬或弥补。','英语 un-“没有”+ compensated；compensated 是 compensate 的过去分词。否定的是已获补偿这一状态。',CO+[['英语 compensate → compensated → uncompensated','给予补偿 → 已补偿 → 未获补偿']],'uncompensated work 是没有获得报酬的工作；uncompensated losses 是没有被补偿的损失。它只说明是否获得补偿，不单凭这个词就说明安排是否合法或是否自愿。','uncompensated work；uncompensated losses；an uncompensated role。','unpaid 常直接说未付钱，uncompensated 还可以说损失未得到任何相应弥补。两者在劳动报酬语境中常重叠。',('The committee role is uncompensated, so members serve as volunteers.','这个委员会职务没有报酬，成员以志愿者身份任职。'),('The report lists the losses that remained uncompensated.','报告列出了仍未获得补偿的损失。'),sources=[K('uncompensated'),'https://dictionary.cambridge.org/us/dictionary/english/uncompensated',S('compensate')]),
E('dispense','英、美 /dɪˈspens/','分发；配发药物；〔dispense with〕省去、不再需要','把东西按份给出去：机器发票，药房配药，人也可以给出建议。加 with 后，则常表示把某一步或某样东西省掉。','经古法语 dispenser，接拉丁 dispensare，它是 dispendere“分别称出、花出”的反复式。中世纪这个词族还有准予豁免的用法，帮助理解 dispense with“免去、不用”。',DI+[['古法语 dispenser → 中古英语 dispensen → dispense','分配、给予；准予免除的相关用法'],['英语 dispense with','省去某物或不再需要某人某物']],'dispense medicine 是配发药物；dispense advice 是给出建议。dispense with the introduction 则是省去开场介绍，with 让常用意思发生明显变化。','dispense medicine；dispense advice；dispense tickets；dispense with formalities。','disperse 是散开，dispense 是分发。dispense something 是给出它；dispense with something 常是省去它。',('The machine dispenses a ticket when you press the button.','按下按钮，机器就会出一张票。'),('We can dispense with the long introduction and begin the discussion.','我们可以省去冗长的开场，直接开始讨论。'),sources=[S('dispense'),K('dispense'),O('dispense')]),
E('dispenser','英 /dɪˈspensə/；美 /dɪˈspensər/','分发器；出液器；配发药物等的人','需要多少就给出一些的装置，比如按一次出一点肥皂液；也可指负责配发的人。','早期经古法语 despenseor、盎格鲁法语 dispensour，接拉丁 dispensator。现代可按 dispense + -er 理解其作用，但人称名词有自己的借入路线，机器义则是后来的扩展。',DI+[['拉丁 dispensator → 古法语 despenseor／盎格鲁法语 dispensour','负责分配、管理或给予的人'],['英语 dispenser','分配者；后来也指按份给出物品的装置']],'a soap dispenser 是皂液器；a water dispenser 是饮水装置；a medicine dispenser 可以指装置，也可能是配发药物的人，需看场景。','a soap dispenser；a water dispenser；a ticket dispenser；refill a dispenser。','container 只强调盛放东西，dispenser 强调能把内容物分发、释放出来。不是所有装着液体的瓶子都特别称 dispenser。',('The soap dispenser beside the sink was empty.','水槽旁的皂液器空了。'),('A dispenser at the clinic checked the label before handing over the medicine.','诊所的配药人员在交出药品前核对了标签。'),sources=[S('dispenser'),K('dispenser'),O('dispenser')]),
E('dispensary','英 /dɪˈspensəri/；美 /dɪˈspensəri/','药房；配药室；提供基本诊疗、药物的小型机构','去那里领取药物，某些地方还提供基本医疗服务。这个词突出药物的配发地点。','接中世纪拉丁 dispensarium，相关形容词 dispensarius 来自 dispensare“分配”。现代可以借 dispense 记住意思，但不是只能当作英语动词临时加 -ary 的新造词。',DI+[['中世纪拉丁 dispensarius／名词 dispensarium','与配发有关的；配发物品的地方'],['英语 dispensary','配药室、药房；部分地区的小型医疗机构']],'a hospital dispensary 是医院配药部门；a rural dispensary 在一些地区是提供基本医疗和药物的诊所。北美部分场景中也会指依法供应大麻制品的门店，需看具体上下文。','a hospital dispensary；a rural dispensary；work in the dispensary。','pharmacy 很常见，可指药房或药学；dispensary 更突出配发药物的地点，有时规模和职能依地区而变。',('The patient collected the medicine from the hospital dispensary.','病人从医院药房领取了药物。'),('The village dispensary opens three mornings a week.','村里的小诊所每周有三个上午开门。'),sources=[S('dispensary'),K('dispensary'),O('dispensary')]),
E('indispensable','英、美 /ˌɪndɪˈspensəbəl/','必不可少的；不可或缺的','少了它，事情就很难办或办不成。强调它对当前任务非常关键。','经法语 indispensable 等来源，接否定 in- 与拉丁 dispensare 词族。早期涉及不能获得豁免、不能免去的要求，后来扩展成不能省掉的必要事物；资料对相应中世纪拉丁形式是否为重构有不同标法。',DI+[['法语 indispensable；中世纪拉丁词族背景','in- 否定“可免去、可豁免”'],['英语 indispensable','不能省去 → 必不可少的']],'an indispensable tool 是极其必要的工具；indispensable to the team 是对团队不可或缺。日常也常用来表达强烈重视，并非永远不可能找到替代品。','indispensable to；indispensable for；an indispensable tool；prove indispensable。','important 只是重要，indispensable 更强，接近“缺了不行”。independent 是独立，indispensable 是不可缺，不能因开头相似而混用。',('A clear map proved indispensable on the long walk.','在这次长途步行中，一张清晰的地图发挥了不可缺少的作用。'),('Her knowledge of the local language was indispensable to the team.','她对当地语言的了解对团队不可或缺。'),sources=[S('indispensable'),K('indispensable'),O('indispensable')]),
E('dispensable','英、美 /dɪˈspensəbəl/','可以省去的；并非必需的；可替代的','把它拿走，主要事情依然能够继续，所以并非缺它不可。','接中世纪拉丁 dispensabilis，与 dispensare“准予豁免、分配”有关；现代也能按 dispense with + -able 理解。早期“可豁免”逐渐扩展为“可省掉”。',DI+[['中世纪拉丁 dispensabilis → 英语 dispensable','可获豁免的 → 可以省去的'],['现代一般用法','非必要、可不使用或可被替代的']],'dispensable details 是可删去的细节；feel dispensable 是觉得自己可有可无。说人 dispensable 往往会显得冷漠，表示对方的作用不被珍惜。','dispensable details；a dispensable feature；feel dispensable；entirely dispensable。','indispensable 加 in- 后正好反过来，表示不可或缺。expendable 常强调可以消耗、牺牲，dispensable 更强调可以不用。',('Several decorative features are dispensable if we need to reduce costs.','如果需要降低成本，有些装饰功能可以省去。'),('The manager’s remarks made experienced staff feel dispensable.','经理的话让经验丰富的员工觉得自己可有可无。'),sources=[S('dispensable'),K('dispensable'),O('dispensable')]),
E('expend','英、美 /ɪkˈspend/','花费；耗费；投入资源','把有限的钱、力气或努力花出去，通常用比较正式的语气强调资源消耗。','借拉丁 expendere：ex-“向外”+ pendere“称量、支付”。早年的称钱、付钱帮助理解用资源的意思，但现代不必真的先称重。',[['拉丁 pendere“称量、支付”','衡量并付出'],['拉丁 ex- + pendere → expendere','向外付出、花费'],['英语 expend','正式用语：花费时间、资金、精力等']],'expend energy 是耗费能量；expend effort on a task 是在任务上付出努力。它通常比 spend 正式，也更关注资源的投入，而不是一般地说度过某天。','expend energy；expend effort；expend resources on；expend time and money。','spend the weekend 很自然，expend the weekend 通常不这样说。expend 侧重消耗资源，spend 还可以泛指度过时间。',('We expended too much effort on a minor formatting issue.','我们在一个很小的格式问题上花费了太多精力。'),('The device expends less energy when it is idle.','这台设备空闲时耗能更少。'),sources=[S('expend'),K('expend'),O('expend')]),
E('expenditure','英 /ɪkˈspendɪtʃə/；美 /ɪkˈspendɪtʃər/','支出；支出额；资源的耗费','把花出去的资源记成一项总量，常出现在预算、报告和正式说明里。','由中世纪拉丁 expenditus 的词干与 -ure 形成；expenditus 是 expendere 的一种非古典分词形式。现代与 expend 对应，但不能把 -iture 当成这里可随意加给英语动词的通用后缀。',[['拉丁 expendere','花费、付出'],['中世纪拉丁 expenditus 词干 + -ure','采用花费的分词词干形成名词'],['英语 expenditure','花费行为或花费总额；也可指具体支出项']],'government expenditure 是政府支出；expenditure on maintenance 是维护方面的花费。energy expenditure 说能量消耗，未必涉及钱。复数 expenditures 在财务报告中也常见。','public expenditure；capital expenditure；expenditure on；reduce expenditure。','income 是收入，expenditure 是支出；budget 是计划，可以同时安排两者。expenses 更常说具体费用，expenditure 语气更正式。',('The report separates expenditure on repairs from expenditure on new equipment.','报告把维修支出与新设备支出分开列出。'),('The study compared energy expenditure during different activities.','研究比较了不同活动中的能量消耗。'),sources=[S('expenditure'),K('expenditure'),O('expenditure')]),
E('expendable','英、美 /ɪkˈspendəbəl/','可消耗的；可替换的；被认为可以牺牲的','用完可以补，损失了也被认为能够承受。用于人时，会让人感到自己被当作随时可丢弃的资源。','英语 expend + -able；原来是可花费、可用掉的，再扩展为损失后可替换、可牺牲。它不含 expensive“昂贵”的意思。',[['拉丁 expendere → 英语 expend','花费、耗用'],['英语 expend + -able → expendable','可以耗用的 → 可被替换或舍弃的']],'expendable supplies 可指用后需补充的物资；treat workers as expendable 是把工人看作可以随便替换的人，常带批评。它说可被消耗或放弃，不必表示价值真的低。','expendable supplies；expendable resources；treat someone as expendable。','dispensable 重在不是必需，可以省掉；expendable 重在可以被消耗、失去或牺牲。expensive 只说花费高。',('The budget distinguishes reusable equipment from expendable supplies.','预算区分了可重复使用的设备和消耗性物资。'),('The workers objected to being treated as expendable.','工人们反对被当作可以随意替换的人。'),sources=[S('expendable'),K('expendable'),O('expendable')]),
E('pensive','英、美 /ˈpensɪv/','沉思的；若有所思而略带忧郁的','人安静下来，心里像在反复掂量一件事，神情往往有点忧伤或心事重重。','经古法语 pensif，来自 penser“思考”，再接拉丁 pensare“称量、权衡”。这里的 pens- 不是钢笔 pen；从称东西的轻重，走到衡量心中的问题。',PE,'a pensive look 是若有所思的神情；a pensive mood 是沉思、略忧郁的心境。它不意味着一定在作严密推理，更常用于描写小说人物、照片或场景气氛。','a pensive expression；a pensive mood；look pensive；fall silent and pensive。','thoughtful 可以表示深思，也可以表示体贴；pensive 通常是沉思、带心事，不表示待人周到。',('She grew pensive as the train passed her childhood home.','火车经过她童年住过的地方时，她变得若有所思。'),('The portrait captures his quiet, pensive expression.','这幅肖像捕捉到了他安静而沉思的神情。'),sources=[S('pensive'),K('pensive'),O('pensive')]),
E('pensively','英、美 /ˈpensɪvli/','沉思地；若有所思地','看、坐、说话都慢下来，像心思还停在另一件需要反复回想的事上。','英语 pensive + -ly。副词描写一种沉思、常带忧郁的状态怎样表现在动作中。',PE+[['英语 pensive + -ly → pensively','以沉思、带心事的方式']],'gaze pensively 是若有所思地凝视；sit pensively 是静静沉思地坐着。常见于叙事和人物描写，不等于已经思考出了结论。','gaze pensively；look pensively at；sit pensively；say pensively。','carefully 强调小心、认真地操作或检查；pensively 强调心有所思的神情。',('He stared pensively at the empty chair.','他若有所思地望着那把空椅子。'),('“Perhaps we should have stayed longer,” she said pensively.','“也许我们本该多留一会儿。”她沉思着说。'),sources=[K('pensively'),O('pensively'),S('pensive')]),
E('pensiveness','英、美 /ˈpensɪvnəs/','沉思；若有所思的忧郁状态','把那种安静、有心事、反复回想的神情或情绪当作一种状态来说。','英语 pensive + -ness，把形容词变为状态名词。它承接 pensive 的沉思色彩，不是泛指任何一种思维能力。',PE+[['英语 pensive + -ness → pensiveness','沉思、略带忧郁的状态']],'a moment of pensiveness 是一会儿沉思；pensiveness in someone’s face 是脸上的若有所思。它常用于人物、文学和艺术描写，通常不可数。','a moment of pensiveness；a mood of pensiveness；a trace of pensiveness。','sadness 是悲伤，pensiveness 还包含沉浸于思考的感觉。concentration 是集中注意，不一定有忧郁色彩。',('A trace of pensiveness remained in her smile.','她的微笑里仍留着一丝若有所思。'),('The music gave way to a mood of quiet pensiveness.','音乐转为一种安静沉思的情绪。'),sources=[K('pensiveness'),'https://www.collinsdictionary.com/dictionary/english/pensiveness',S('pensive')]),
]
